<?php require __DIR__.'/../app/bootstrap.php'; require __DIR__.'/../app/layout.php'; require_super_admin();$locs=db()->query('SELECT id,code,name FROM locations WHERE active=1 ORDER BY code')->fetchAll();$err='';$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$barcode=trim($_POST['barcode']??'');$location=(int)($_POST['location_id']??0);$qty=(float)($_POST['quantity']??0);$reason=trim($_POST['reason']??'');if($barcode===''||$qty<=0||$reason==='')$err='Barcode, quantity and reason are required.';else try{db()->beginTransaction();
 $st=db()->prepare("SELECT ps.*,b.supplier_id,b.purchase_id,b.cost_price,p.serial_tracking FROM product_serials ps JOIN batches b ON b.id=ps.batch_id JOIN products p ON p.id=ps.product_id WHERE ps.serial_barcode=? AND ps.location_id=? FOR UPDATE");$st->execute([$barcode,$location]);$serial=$st->fetch();$productId=$batchId=$supplierId=0;$purchaseId=null;$cost=0;$retQty=$qty;$serialId=null;
 if($serial){if($serial['status']!=='AVAILABLE')throw new Exception('Unique piece is not available for supplier return.');if(abs($qty-1)>0.0001)throw new Exception('Unique piece return quantity must be 1.');$productId=(int)$serial['product_id'];$batchId=(int)$serial['batch_id'];$supplierId=(int)$serial['supplier_id'];$purchaseId=$serial['purchase_id']?(int)$serial['purchase_id']:null;$cost=(float)$serial['cost_price'];$retQty=1;$serialId=(int)$serial['id'];}
 else {$st=db()->prepare('SELECT ib.product_id,ib.batch_id,ib.qty,ib.reserved_qty,b.supplier_id,b.purchase_id,b.cost_price,p.serial_tracking FROM inventory_balances ib JOIN batches b ON b.id=ib.batch_id JOIN products p ON p.id=ib.product_id WHERE ib.location_id=? AND (ib.qty-ib.reserved_qty)>0 AND (b.batch_barcode=? OR p.product_barcode=?) ORDER BY b.purchased_at LIMIT 1 FOR UPDATE');$st->execute([$location,$barcode,$barcode]);$r=$st->fetch();if(!$r)throw new Exception('Barcode not found at selected location.');if((int)$r['serial_tracking']===1)throw new Exception('Serialized garment: scan individual unique barcode.');if(((float)$r['qty']-(float)$r['reserved_qty'])<$qty)throw new Exception('Insufficient sellable stock; reserved online stock cannot be returned to supplier.');$productId=(int)$r['product_id'];$batchId=(int)$r['batch_id'];$supplierId=(int)$r['supplier_id'];$purchaseId=$r['purchase_id']?(int)$r['purchase_id']:null;$cost=(float)$r['cost_price'];}
 $st=db()->prepare('SELECT qty,reserved_qty FROM inventory_balances WHERE product_id=? AND batch_id=? AND location_id=? FOR UPDATE');$st->execute([$productId,$batchId,$location]);$bal=$st->fetch();if(!$bal||((float)$bal['qty']-(float)$bal['reserved_qty'])<$retQty)throw new Exception('Insufficient sellable stock.');$returnNo='PRT-'.date('YmdHis').'-'.random_int(10,99);$value=$retQty*$cost;db()->prepare('INSERT INTO purchase_returns(return_no,purchase_id,supplier_id,total_value,reason,created_by) VALUES(?,?,?,?,?,?)')->execute([$returnNo,$purchaseId,$supplierId,$value,$reason,current_user()['id']]);$rid=(int)db()->lastInsertId();db()->prepare('INSERT INTO purchase_return_items(purchase_return_id,product_id,batch_id,location_id,serial_id,quantity,cost_price) VALUES(?,?,?,?,?,?,?)')->execute([$rid,$productId,$batchId,$location,$serialId,$retQty,$cost]);db()->prepare('UPDATE inventory_balances SET qty=qty-? WHERE product_id=? AND batch_id=? AND location_id=?')->execute([$retQty,$productId,$batchId,$location]);db()->prepare('UPDATE batches SET qty_available=qty_available-? WHERE id=?')->execute([$retQty,$batchId]);if($serialId)db()->prepare("UPDATE product_serials SET status='RETURNED_SUPPLIER' WHERE id=?")->execute([$serialId]);db()->prepare("INSERT INTO stock_ledger(txn_type,product_id,batch_id,location_id,qty_out,reference_type,reference_id,unit_rate,remarks,created_by) VALUES('PURCHASE_RETURN',?,?,?,?, 'PURCHASE_RETURN',?,?,?,?)")->execute([$productId,$batchId,$location,$retQty,$rid,$cost,$reason,current_user()['id']]);db()->prepare("INSERT INTO supplier_ledger(supplier_id,txn_type,debit,reference_type,reference_id,remarks,created_by) VALUES(?,'PURCHASE_RETURN',?,'PURCHASE_RETURN',?,?,?)")->execute([$supplierId,$value,$rid,$returnNo,current_user()['id']]);maybe_publish_low_stock($productId,$location);db()->commit();audit('PURCHASE_RETURN','purchase_return',$rid,['barcode'=>$barcode,'qty'=>$retQty,'value'=>$value]);$msg=$returnNo.' completed. Stock and supplier payable reduced.';
 }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$err=$e->getMessage();}}
page_header('Purchase Return / Return to Supplier');if($err)echo '<div class="notice error">'.e($err).'</div>';if($msg)echo '<div class="notice success">'.e($msg).'</div>'; ?>
<form method="post" class="panel"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="row3"><div><label>Scan Unique/Batch Barcode</label><input name="barcode" class="scanbox" data-scanner required></div><div><label>Location</label><select name="location_id"><?php foreach($locs as $l):?><option value="<?=$l['id']?>"><?=e($l['code'].' · '.$l['name'])?></option><?php endforeach;?></select></div><div><label>Quantity</label><input type="number" step="0.001" min="0.001" name="quantity" value="1" required></div></div><br><label>Reason</label><input name="reason" required placeholder="Supplier return reason"><br><br><button class="btn danger">RETURN STOCK TO SUPPLIER</button></form><?php page_footer();
